package agentusageview

import (
	"fmt"
	"log"
	"math"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage/pricing"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

const (
	// minus is the real minus sign (U+2212), never an ASCII hyphen.
	minus = "−"
	// estimateMark prefixes an amount computed from a user-written price table.
	estimateMark = "~"
	// costWidth fits the widest sub-agent cell, "≥ ~$999.99".
	costWidth = 10
	// wholeDollarsFrom is where cents stop being shown.
	wholeDollarsFrom = 999.995
	// maxDollars is the largest amount shown exactly; past it the cell saturates.
	maxDollars = 99999.5
	// saturated is what formatUSD shows past maxDollars: "at least".
	saturated = "$99999+"
)

// formatUSD renders an amount: two decimals up to $999.99, whole dollars from
// $1000, "$99999+" past $99999. A non-zero amount under half a cent is
// "<$0.01", never "$0.00". The estimate mark is costCell's, not this function's.
func formatUSD(v float64) string {
	if v < 0 {
		return minus + formatUSD(-v)
	}
	switch {
	case v >= maxDollars:
		return saturated
	case v >= wholeDollarsFrom:
		return fmt.Sprintf("$%.0f", math.Floor(v+0.5))
	case v > 0 && v < 0.005:
		return "<$0.01"
	}
	return fmt.Sprintf("$%.2f", v)
}

// costCell is the Est. cost cell: an estimate for the orchestrator, a floor
// (partialMark) for a sub-agent, whose transcript may be incomplete; a dash
// when the cost is unknown. A saturated amount already means "at least", so a
// sub-agent drops the floor mark to stay within costWidth.
func costCell(r agentRow) string {
	if r.cost.Status != pricing.Priced {
		return noValue
	}
	amount := formatUSD(r.cost.USD)
	if r.Main || amount == saturated {
		return estimateMark + amount
	}
	return partialMark + estimateMark + amount
}

// costColumn is the Est. cost column. It has no Less: `.` keeps cycling Total.
func costColumn() datatable.Column[agentRow] {
	return datatable.Column[agentRow]{
		Title: "Est. cost", Sizing: datatable.SizingFixed, MinWidth: costWidth, Optional: true, DropFirst: true,
		Cell:  costCell,
		Style: func(r agentRow) lipgloss.Style { return dimWhen(r.cost.Status != pricing.Priced) },
	}
}

// pricesFrom builds the price table of a context. The table is read once, when
// the view is built, and a rejected entry is logged once, naming the user's key.
func pricesFrom(cfg *config.Config) pricing.Table {
	if cfg == nil {
		return pricing.Table{}
	}
	table, problems := pricing.FromConfig(cfg.AgentUsage.Prices)
	for _, p := range problems {
		log.Printf("WARN [agentusageview] agent_usage.prices %q: %s", p.Key, p.Reason)
	}
	return table
}
package pricing

import (
	"math"
	"sort"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// noModelLabel names the bucket of tokens recorded under no model.
const noModelLabel = "(no model)"

// Status tells what an Estimate holds.
type Status int

const (
	// NoTokens means there was nothing to price; USD is 0 and means nothing.
	NoTokens Status = iota
	// Priced means every model with tokens has a rate; USD is the cost.
	Priced
	// Unpriced means at least one model with tokens has no rate. USD is 0 and
	// must not be shown: a partial sum would under-state without saying so.
	Unpriced
)

// Estimate is the indicative cost of an agent, or of a sum of agents.
type Estimate struct {
	USD    float64
	Status Status
	// Unpriced lists the models with tokens and no rate, in first-appearance
	// order; the bucket of no model is "(no model)".
	Unpriced []string
}

// Cost returns the cost in USD of one model's tokens. The 5 minute cache
// write is the total write minus its 1 hour part.
func (r Rates) Cost(m agentusage.ModelUsage) float64 {
	t := m.Tokens
	return (float64(t.Input)*r.Input +
		float64(t.Output)*r.Output +
		float64(m.CacheWrite5m())*r.CacheWrite5m +
		float64(m.CacheWrite1h)*r.CacheWrite1h +
		float64(t.CacheRead)*r.CacheRead) / perMillion
}

// hasTokens reports whether a model bucket carries any token.
func hasTokens(m agentusage.ModelUsage) bool {
	t := m.Tokens
	return t.Input != 0 || t.Output != 0 || t.CacheRead != 0 || t.CacheWrite != 0
}

// Agent estimates one agent. It never returns a partial cost: one model with
// tokens and no rate makes the whole agent Unpriced.
func (t Table) Agent(a agentusage.Agent) Estimate {
	var e Estimate
	buckets := a.ByModel
	if len(buckets) == 0 && a.Tokens != (agentusage.Tokens{}) {
		// Tokens without a split cannot be priced per model.
		buckets = []agentusage.ModelUsage{{Tokens: a.Tokens}}
	}
	for _, m := range buckets {
		if !hasTokens(m) {
			continue
		}
		e.Status = Priced
		r, ok := t.Lookup(m.Model)
		if !ok {
			e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
			continue
		}
		cost := r.Cost(m)
		if !isFinite(cost) {
			// A huge rate times a huge count is not a cost worth showing.
			e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
			continue
		}
		e.USD += cost
	}
	if len(e.Unpriced) > 0 || !isFinite(e.USD) {
		return Estimate{Status: Unpriced, Unpriced: e.Unpriced}
	}
	return e
}

// isFinite reports whether f is neither NaN nor an infinity.
func isFinite(f float64) bool { return !math.IsNaN(f) && !math.IsInf(f, 0) }

func modelLabel(model string) string {
	if model == "" {
		return noModelLabel
	}
	return model
}

func appendOnce(list []string, s string) []string {
	for _, x := range list {
		if x == s {
			return list
		}
	}
	return append(list, s)
}

// Sum adds estimates: Unpriced if any is, NoTokens if all are.
func Sum(es []Estimate) Estimate {
	var out Estimate
	for _, e := range es {
		switch e.Status {
		case Priced:
			out.USD += e.USD
			if out.Status == NoTokens {
				out.Status = Priced
			}
		case Unpriced:
			out.Status = Unpriced
			for _, m := range e.Unpriced {
				out.Unpriced = appendOnce(out.Unpriced, m)
			}
		}
	}

content.content:
	}
	if !isFinite(out.USD) {
		// The sum of finite estimates can still overflow.
		out.Status = Unpriced
	}
	if out.Status == Unpriced {
		out.USD = 0
	}
	return out
}

// Summary is the cost picture of a whole session.
type Summary struct {
	Agents []Estimate // same order as Usage.Agents
	Billed agentusage.Billed
	// Unattributed is Billed minus the agents' estimates; it may be negative
	// (the price table is higher than what was recorded). It is meaningful
	// only when UnattributedKnown.
	Unattributed      float64
	UnattributedKnown bool
	Unpriced          []string // sorted, distinct, over the whole session
}

// Session estimates every agent of a session. Unattributed is known only when
// Billed is known and every agent with tokens is priced.
func (t Table) Session(u agentusage.Usage) Summary {
	s := Summary{Agents: make([]Estimate, len(u.Agents)), Billed: u.Billed}
	for i, a := range u.Agents {
		s.Agents[i] = t.Agent(a)
	}
	total := Sum(s.Agents)
	s.Unpriced = total.Unpriced
	sort.Strings(s.Unpriced)
	if u.Billed.Known && total.Status != Unpriced {
		s.Unattributed = u.Billed.USD - total.USD
		s.UnattributedKnown = true
	}
	return s
}
package agentusageview

import (
	"path/filepath"
	"strconv"

	"github.com/charmbracelet/lipgloss"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string {
	if m.level == levelAgents {
		return m.agentTable.View()
	}
	return m.table.View()
}

// GetTitle names the view, and the project of the open session at the agents
// level (its short ID when the transcript named no project).
func (m Model) GetTitle() string {
	title := theme.IconAgentUsage + " Agent usage"
	if m.level != levelAgents {
		return title
	}
	leaf := shortID(m.open.ID)
	if m.open.Project != "" {
		leaf = filepath.Base(m.open.Project)
	}
	return title + " › " + leaf
}

// shortID is the start of a session ID, as the Session column shows it.
func shortID(id string) string {
	r := []rune(id)
	return string(r[:min(sessionIDPrefix, len(r))])
}

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	if m.level == levelAgents {
		return m.agentsHeaderInfo()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// agentsHeaderInfo counts the agents on screen and their tokens, both following
// the filter.
func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
	rows := m.agentTable.Visible()
	var total int64
	for _, r := range rows {
		total += r.Tokens.Total()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
		{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
		{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle},
	}
	if n := m.idleCount(); n > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Idle", Value: strconv.Itoa(n), Style: theme.HeaderValueStyle})
	}
	return info
}

// idleCount counts the idle agents over every row, not just the visible ones:
// an alert must not hide behind a filter.
func (m Model) idleCount() int {
	n := 0
	for _, r := range m.agentTable.Items() {
		if r.state == stateIdle {
			n++
		}
	}
	return n
}

// updatesState says whether the open session is polled: live while the chain
// runs, paused once it stopped (settled session, deleted transcript).
func (m Model) updatesState() string {
	if m.level == levelAgents && m.agg != nil && !m.pollStopped {
		return "live"
	}
	return "paused"
}

// GetShortcuts returns the same keys at both levels and in every state; what
// varies is Disabled, from the one availability the handlers also read
// (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	a := m.availability()
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
		{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
		{Key: "/", Description: "Filter"},
		{Key: ".", Description: "Sort"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	h := baseFooterHeight + m.activeFilterBar().ExtraHeight()
	if m.level == levelAgents {
		h++ // the breadcrumb row
	}
	return h
}

// RenderFooter renders the breadcrumb at the agents level, the filter bar when
// visible, a blank line, and the message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.activeFilterBar(); bar.IsVisible() {
		line = bar.View() + "\n" + line
	}
	if m.level == levelAgents {
		line = m.breadcrumb(width) + "\n" + line
	}
	return line
}

// breadcrumb is Sessions › project › ID, the last one active and its parents
// dim, with the one cell of left padding Rule 123 asks for.
func (m Model) breadcrumb(width int) string {
	project := noProject
	if m.open.Project != "" {
		project = theme.ShortPath(m.open.Project, max(width/2, 1))
	}
	base := lipgloss.NewStyle().Background(theme.ColorBackground)
	parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
	active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
	return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	case m.usage.Diagnostics.Degraded():
		return sharedcomponents.Status{
			Text:  "Totals are approximate — some transcript data could not be read",
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{}
}
package agentusageview

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/agentusage/pricing"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// noValue is the dash of a cell with nothing to show.
	noValue = "-"
	// noModel stands for an agent whose transcript named no model.
	noModel = noValue
	// unknownID stands for a sub-agent whose ID is empty, so it cannot be
	// mistaken for the orchestrator, which has no short ID by design.
	unknownID = "?"
	// unknownType stands for a sub-agent whose meta file gave no type.
	unknownType = "unknown"
	// orchestratorLabel is the Agent cell of the main agent.
	orchestratorLabel = "orchestrator"
	// partialMark prefixes an output count that is a floor, not an exact value.
	partialMark = "≥ "
	// stem and lastStem draw the tree branch in front of a sub-agent's type.
	stem     = "├─ "
	lastStem = "└─ "
)

// agentIDPrefix is the shortest agent ID shown.
const agentIDPrefix = 8

// agentRow is one line of the agents table.
type agentRow struct {
	agentusage.Agent
	branch  string   // stem, lastStem, or "" (orchestrator, or a sorted list)
	shortID string   // ID prefix, distinct within the session; "" for the orchestrator
	share   int      // tenths of a percent of the session total, or noShare
	key     string   // identity across rebuilds, see agentKeys
	state   runState // what the State column shows
	cost    pricing.Estimate
}

// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
// gives each its short ID and share, and draws the branches when tree is true.
// The sort is stable so equal IDs keep their input order.
func agentRows(u agentusage.Usage, tree bool, c statusClock, prices pricing.Table) []agentRow {
	var main, subs []agentusage.Agent
	for _, a := range u.Agents {
		if a.Main {
			main = append(main, a)
		} else {
			subs = append(subs, a)
		}
	}
	sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })

	ordered := append(append([]agentusage.Agent{}, main...), subs...)
	totals := make([]int64, len(ordered))
	for i, a := range ordered {
		totals[i] = a.Tokens.Total()
	}
	mainIdx := -1
	if len(main) > 0 {
		mainIdx = 0
	}
	parts := shares(totals, u.Total().Total(), mainIdx)

	ids := make([]string, len(subs))
	for i, a := range subs {
		ids[i] = a.ID
	}
	short := shortAgentIDs(ids)

	keys := agentKeys(ordered)
	states := agentStates(ordered, c)
	rows := make([]agentRow, 0, len(ordered))
	for i, a := range ordered {
		row := agentRow{Agent: a, share: parts[i], key: keys[i], state: states[i], cost: prices.Agent(a)}
		if !a.Main {
			j := i - len(main)
			row.shortID = short[j]
			if tree {
				row.branch = stem
				if j == len(subs)-1 {
					row.branch = lastStem
				}
			}
		}
		rows = append(rows, row)
	}
	return rows
}

// shortAgentIDs cuts every ID to one common length, the smallest n >=
// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
// own length.
func shortAgentIDs(ids []string) []string {
	if len(ids) == 0 {
		return nil
	}
	longest := 0
	runes := make([][]rune, len(ids))
	for i, id := range ids {
		runes[i] = []rune(id)
		longest = max(longest, len(runes[i]))
	}
	cut := func(n int) []string {
		out := make([]string, len(runes))
		for i, r := range runes {
			out[i] = string(r[:min(n, len(r))])
		}
		return out
	}
	for n := agentIDPrefix; n < longest; n++ {
		seen := make(map[string]bool, len(ids))
		distinct := true
		for _, s := range cut(n) {
			if seen[s] {
				distinct = false
				break
			}
			seen[s] = true
		}
		if distinct {
			return cut(n)
		}
	}
	return cut(longest)
}

// agentColumns describes the agents table. Only Total sorts, largest first;
// without a sort the order is the tree. Columns give way on a narrow terminal
// in this order: Cache write, Est. cost, Cache read, In, Model, Duration, Tools, State

toolUseResult.stdout:
	}
	if !isFinite(out.USD) {
		// The sum of finite estimates can still overflow.
		out.Status = Unpriced
	}
	if out.Status == Unpriced {
		out.USD = 0
	}
	return out
}

// Summary is the cost picture of a whole session.
type Summary struct {
	Agents []Estimate // same order as Usage.Agents
	Billed agentusage.Billed
	// Unattributed is Billed minus the agents' estimates; it may be negative
	// (the price table is higher than what was recorded). It is meaningful
	// only when UnattributedKnown.
	Unattributed      float64
	UnattributedKnown bool
	Unpriced          []string // sorted, distinct, over the whole session
}

// Session estimates every agent of a session. Unattributed is known only when
// Billed is known and every agent with tokens is priced.
func (t Table) Session(u agentusage.Usage) Summary {
	s := Summary{Agents: make([]Estimate, len(u.Agents)), Billed: u.Billed}
	for i, a := range u.Agents {
		s.Agents[i] = t.Agent(a)
	}
	total := Sum(s.Agents)
	s.Unpriced = total.Unpriced
	sort.Strings(s.Unpriced)
	if u.Billed.Known && total.Status != Unpriced {
		s.Unattributed = u.Billed.USD - total.USD
		s.UnattributedKnown = true
	}
	return s
}
package agentusageview

import (
	"path/filepath"
	"strconv"

	"github.com/charmbracelet/lipgloss"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string {
	if m.level == levelAgents {
		return m.agentTable.View()
	}
	return m.table.View()
}

// GetTitle names the view, and the project of the open session at the agents
// level (its short ID when the transcript named no project).
func (m Model) GetTitle() string {
	title := theme.IconAgentUsage + " Agent usage"
	if m.level != levelAgents {
		return title
	}
	leaf := shortID(m.open.ID)
	if m.open.Project != "" {
		leaf = filepath.Base(m.open.Project)
	}
	return title + " › " + leaf
}

// shortID is the start of a session ID, as the Session column shows it.
func shortID(id string) string {
	r := []rune(id)
	return string(r[:min(sessionIDPrefix, len(r))])
}

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	if m.level == levelAgents {
		return m.agentsHeaderInfo()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// agentsHeaderInfo counts the agents on screen and their tokens, both following
// the filter.
func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
	rows := m.agentTable.Visible()
	var total int64
	for _, r := range rows {
		total += r.Tokens.Total()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
		{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
		{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle},
	}
	if n := m.idleCount(); n > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Idle", Value: strconv.Itoa(n), Style: theme.HeaderValueStyle})
	}
	return info
}

// idleCount counts the idle agents over every row, not just the visible ones:
// an alert must not hide behind a filter.
func (m Model) idleCount() int {
	n := 0
	for _, r := range m.agentTable.Items() {
		if r.state == stateIdle {
			n++
		}
	}
	return n
}

// updatesState says whether the open session is polled: live while the chain
// runs, paused once it stopped (settled session, deleted transcript).
func (m Model) updatesState() string {
	if m.level == levelAgents && m.agg != nil && !m.pollStopped {
		return "live"
	}
	return "paused"
}

// GetShortcuts returns the same keys at both levels and in every state; what
// varies is Disabled, from the one availability the handlers also read
// (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	a := m.availability()
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
		{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
		{Key: "/", Description: "Filter"},
		{Key: ".", Description: "Sort"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	h := baseFooterHeight + m.activeFilterBar().ExtraHeight()
	if m.level == levelAgents {
		h++ // the breadcrumb row
	}
	return h
}

// RenderFooter renders the breadcrumb at the agents level, the filter bar when
// visible, a blank line, and the message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.activeFilterBar(); bar.IsVisible() {
		line = bar.View() + "\n" + line
	}
	if m.level == levelAgents {
		line = m.breadcrumb(width) + "\n" + line
	}
	return line
}

// breadcrumb is Sessions › project › ID, the last one active and its parents
// dim, with the one cell of left padding Rule 123 asks for.
func (m Model) breadcrumb(width int) string {
	project := noProject
	if m.open.Project != "" {
		project = theme.ShortPath(m.open.Project, max(width/2, 1))
	}
	base := lipgloss.NewStyle().Background(theme.ColorBackground)
	parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
	active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
	return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	case m.usage.Diagnostics.Degraded():
		return sharedcomponents.Status{
			Text:  "Totals are approximate — some transcript data could not be read",
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{}
}
