// ── Footer: status precedence (Rule 128, H11) ────────────────────────────────

func degraded() agentusage.Usage {
	u := threeSubs()
	u.Diagnostics.UnreadableLines = 2
	return u
}

func TestDegradedUsageWarnsThatTotalsAreApproximate(t *testing.T) {
	m := atAgents(t, degraded())
	st := m.status()
	if st.Level != sharedcomponents.LevelWarning {
		t.Errorf("level = %v, want LevelWarning", st.Level)
	}
	if !strings.Contains(strings.ToLower(st.Text), "approximate") {
		t.Errorf("status = %q, want it to say the totals are approximate", st.Text)
	}
	if !strings.Contains(footerText(m), "approximate") {
		t.Errorf("footer lacks the approximate warning:\n%s", footerText(m))
	}
}

func TestACleanUsageHasNoStatus(t *testing.T) {
	if st := atAgents(t, threeSubs()).status(); st.Text != "" {
		t.Errorf("status = %+v, want none", st)
	}
}

func TestStatusPrecedenceAtTheAgentsLevel(t *testing.T) {
	// loading wins over degraded
	m := atAgents(t, degraded())
	m.agentsLoading = true
	if st := m.status(); !st.Spinner || strings.Contains(st.Text, "approximate") {
		t.Errorf("loading + degraded = %+v, want the spinner line", st)
	}
	// error wins over loading and degraded
	m.agentsErr = true
	if st := m.status(); st.Level != sharedcomponents.LevelError || st.Spinner {
		t.Errorf("error + loading + degraded = %+v, want the error", st)
	}
}

func TestADegradedUsageIsForgottenWhenAnotherSessionOpens(t *testing.T) {
	m := atAgents(t, degraded())
	m, _ = opened(t, feedBack(t, m), "right")
	if strings.Contains(m.status().Text, "approximate") {
		t.Errorf("a new session starts without the previous one's warning: %+v", m.status())
	}
}

// feedBack returns to the sessions level.
func feedBack(t *testing.T, m Model) Model {
	t.Helper()
	next, _ := opened(t, m, "esc")
func TestTheAgentsLevelHasItsOwnFilter(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl")
	m, _ = opened(t, m, "right")
	m = answer(t, m, threeSubs())

	m = send(t, m, testutil.Key("/"))
	if !m.InEditMode() {
		t.Fatal("/ opens the agents filter")
	}
	for _, k := range testutil.Type("coder") {
		m = feed(t, m, k)
	}
	view := m.View()
	if !strings.Contains(view, "├─ coder") || strings.Contains(view, "orchestrator") {
		t.Errorf("only coder should remain:\n%s", view)
	}
	if m.table.FilterBar().IsVisible() {
		t.Error("the sessions filter must stay untouched")
	}
	// enter while typing confirms the filter; it opens nothing.
	m = send(t, m, testutil.Key("enter"))
	if m.level != levelAgents || m.agentsLoading {
		t.Error("enter in the filter must not reopen the session")
	}
}

// ── Layout (Rules 108, 116) ──────────────────────────────────────────────────

package config

import "gopkg.in/yaml.v3"

// AgentUsageConfig holds the settings of the :agent-usage view. It has no
// default and no migration: an empty section is never written to the file.
type AgentUsageConfig struct {
	// Prices maps a model name, kept exactly as written, to its price per
	// million tokens. Validation (negative, NaN, Inf) belongs to the pricing
	// package, not to the loader.
	Prices map[string]ModelPrice `yaml:"prices,omitempty"`
}

// ModelPrice is the price of one model, per rate. Each rate is optional.
type ModelPrice struct {
	Input        Rate `yaml:"input,omitempty"`
	Output       Rate `yaml:"output,omitempty"`
	CacheWrite5m Rate `yaml:"cache_write_5m,omitempty"`
	CacheWrite1h Rate `yaml:"cache_write_1h,omitempty"`
	CacheRead    Rate `yaml:"cache_read,omitempty"`
}

// RateState tells whether a Rate was absent, unreadable, or a number.
type RateState int

const (
	// RateMissing means the key was absent (or null) in the file.
	RateMissing RateState = iota
	// RateInvalid means the value was not a number (text, list, map, bool).
	RateInvalid
	// RateSet means the value decoded as a number, whatever the number is.
	RateSet
)

// Rate is a tolerant price: a badly typed value costs its own entry, never
// the load of the whole context. The zero value is RateMissing.
type Rate struct {
	state RateState
	value float64
	raw   string     // text of an invalid scalar, written back unchanged
	node  *yaml.Node // copy of an invalid non-scalar (list, map, alias), written back unchanged
}

// Value returns the number and the state; the number is meaningful only for
// RateSet.
func (r Rate) Value() (float64, RateState) { return r.value, r.state }

// IsZero reports a missing rate so that omitempty skips it.
func (r Rate) IsZero() bool { return r.state == RateMissing }

// UnmarshalYAML never returns an error: anything that is not an int or float
// scalar becomes RateInvalid.
func (r *Rate) UnmarshalYAML(node *yaml.Node) error {
	*r = Rate{state: RateInvalid}
	if node.Kind != yaml.ScalarNode {
		cp := *node
		r.node = &cp
		return nil
	}
	r.raw = node.Value
